import React, { useState, useEffect } from 'react'
import './GroupCard.scss'
import axios from 'axios'
import { Pencil, Trash2, BarChartBig } from 'lucide-react'

const GroupCard = ({ groups }) => {
    const [currentPage, setCurrentPage] = useState(1)
    const [groupsPerPage] = useState(3)

    const indexOfLastGroup = currentPage * groupsPerPage;
    const indexOfFirstGroup = indexOfLastGroup - groupsPerPage;
    const currentGroups = groups.slice(indexOfFirstGroup, indexOfLastGroup)
    
    const handleRemoveClick = async (groupName) => {
    try {
        await axios.delete(`http://localhost:8800/group/${groupName}`)
        // Optionally fetch groups again after deletion
    } catch (error) {
        console.error(`Failed to delete group: ${groupName}`, error)
    }
    }

    const paginate = (pageNumber) => {
    setCurrentPage(pageNumber)
    }

    return (
    <div className="group-card-container">
        {currentGroups.map((group) => (
        <div className="card-section" key={group.groupName}>
            <h2 className="group-name">{group.groupName}</h2>
            <Trash2
                className="remove-group-button"
                onClick={() => handleRemoveClick(group.groupName)}
            />
            <div className="group-card-description-section">
                <p className="group-description">{group.description}</p>
            </div>
            <button className="edit-group-button">
                <Pencil />
            </button>
        </div>
        ))}
        <div className="pagination-container">
        {Array.from({ length: Math.ceil(groups.length / groupsPerPage) }).map(
            (_, index) => (
            <button
                    key={index + 1}
                    className={`pagination-button ${
                    currentPage === index + 1 ? "active" : ""
                    }`}
                    onClick={() => paginate(index + 1)}
                    >
                    {index + 1}
                </button>
                )
            )}
            </div>
        </div>
    )
}

export default GroupCard
